def read_file(path):
    return Path(path).read_text()

TOOLS = [{
    "name": "read_file",
    "description": "Read the full text content of a file.",
    "input_schema": {
        "type": "object",
        "properties": {"path": {"type": "string"}},
        "required": ["path"],
    },
}]

def agent_turn(messages):
    while True:
        response = client.messages.create(
            model=MODEL, max_tokens=MAX_TOKENS,
            tools=TOOLS, messages=messages,
        )
        messages.append({"role": "assistant", "content": response.content})

        if response.stop_reason != "tool_use":
            return  # the model is done with this request

        tool_results = []
        for block in response.content:
            if block.type != "tool_use":
                continue
            output = run_tool(block.name, block.input)
            tool_results.append({
                "type": "tool_result",
                "tool_use_id": block.id,  # links the result to the request
                "content": output,
            })

        messages.append({"role": "user", "content": tool_results})

DANGEROUS_TOOLS = {"write_file", "edit_file", "run_bash", "remember"}

def ask_permission(name, tool_input):
    if name not in DANGEROUS_TOOLS or name in always_allowed:
        return True
    preview = tool_input.get("command") or tool_input.get("path") or tool_input.get("fact")
    answer = input(f"  Allow {name}: {preview}?  [y]es / [n]o / [a]lways > ").strip().lower()
    if answer == "a":
        always_allowed.add(name)
        return True
    return answer == "y"

def safe_path(path):
    p = (WORKSPACE / path).resolve()
    if not p.is_relative_to(WORKSPACE):
        raise ToolError(f"Path {path} is outside the workspace {WORKSPACE}")
    return p
